-- 控制平面：部署版本
CREATE TABLE deployments (
  id TEXT PRIMARY KEY NOT NULL,
  recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version >= 1),
  release TEXT NOT NULL,
  build_hash TEXT NOT NULL,
  schema_min INTEGER NOT NULL CHECK (schema_min >= 0),
  schema_max INTEGER NOT NULL CHECK (schema_max >= 0),
  state TEXT NOT NULL CHECK (state IN ('candidate','testing','active','retired','failed')),
  CHECK (schema_min <= schema_max)
) STRICT;

-- 控制平面：进程运行
CREATE TABLE process_runs (
  id TEXT PRIMARY KEY NOT NULL,
  recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version >= 1),
  deployment_id TEXT NOT NULL,
  instance_ref TEXT NOT NULL,
  pid INTEGER CHECK (pid >= 0),
  started_at TEXT NOT NULL,
  exited_at TEXT,
  user_stopped INTEGER NOT NULL CHECK (user_stopped IN (0,1)),
  FOREIGN KEY (deployment_id) REFERENCES deployments(id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

-- 控制平面：唤醒检查
CREATE TABLE wake_checks (
  id TEXT PRIMARY KEY NOT NULL,
  recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version >= 1),
  process_run_id TEXT NOT NULL,
  requested_at TEXT NOT NULL,
  completed_at TEXT,
  result TEXT NOT NULL CHECK (result IN ('pass','fail','unknown')),
  detail TEXT NOT NULL CHECK (json_valid(detail)),
  FOREIGN KEY (process_run_id) REFERENCES process_runs(id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

-- 控制平面：部署切换
CREATE TABLE release_switches (
  id TEXT PRIMARY KEY NOT NULL,
  recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version >= 1),
  old_deployment_id TEXT,
  new_deployment_id TEXT NOT NULL,
  phase TEXT NOT NULL CHECK (phase IN ('prepared','quiesced','stopped','switched','verified','failed')),
  evidence TEXT NOT NULL CHECK (json_valid(evidence)),
  FOREIGN KEY (old_deployment_id) REFERENCES deployments(id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (new_deployment_id) REFERENCES deployments(id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

-- 控制平面：回退
CREATE TABLE rollback_runs (
  id TEXT PRIMARY KEY NOT NULL,
  recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version >= 1),
  switch_id TEXT NOT NULL,
  target_deployment_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  compatibility_result TEXT NOT NULL CHECK (compatibility_result IN ('pass','fail','unknown')),
  result TEXT NOT NULL CHECK (result IN ('pending','succeeded','failed')),
  FOREIGN KEY (switch_id) REFERENCES release_switches(id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (target_deployment_id) REFERENCES deployments(id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

-- 控制平面：备份清单
CREATE TABLE backup_manifests (
  id TEXT PRIMARY KEY NOT NULL,
  recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version >= 1),
  deployment_id TEXT NOT NULL,
  snapshot_path TEXT NOT NULL,
  hash TEXT NOT NULL,
  scope TEXT NOT NULL CHECK (json_valid(scope)),
  completed_at TEXT NOT NULL,
  FOREIGN KEY (deployment_id) REFERENCES deployments(id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE INDEX ix_process_runs_deployment_id ON process_runs(deployment_id);

